public void consume(String event) {
    jdbc.sql("""
            INSERT INTO timeline_entry (viewer_id, post_id, published_at_ms)
            SELECT f.follower_id, p.id, p.published_at_ms
            FROM posts p JOIN follow f ON f.followee_id = p.author_id
            WHERE p.id = :post AND p.deleted_at IS NULL AND NOT p.pull_on_read
            ON CONFLICT (viewer_id, post_id) DO NOTHING
            """)
            .param("post", Long.parseLong(event)).update();
}

